        if (n == 1 || str[0] == '0') return 0;
        long count = 0;
        int underscoreCount = 0;
        for (int i = 1; i < n - 2; i++) {
            if (str[i] == '_') underscoreCount++;
        }
        count += checkPattern(str, "25", n, underscoreCount);
        count += checkPattern(str, "50", n, underscoreCount);
        count += checkPattern(str, "75", n, underscoreCount);

        if (n > 2 && (str[0] == '_' || str[0] == '0')) {
            count *= 9;
        }

        if (n >= 3) {
            if ((str[n - 1] == '_' || str[n - 1] == '0') && (str[n - 2] == '_' || str[n - 2] == '0')) {
                long temp = (long) Math.pow(10, underscoreCount);
                if (str[0] == '_') temp *= 9;
                count += temp;
            }
        }
        return count;
    }

