import sys

def read_int():
    return int(sys.stdin.readline().strip())

def read_strings():
    return sys.stdin.readline().strip().split()

def read_ints():
    parts = read_strings()
    return list(map(int, parts))

def replace_x_with_char(array, length, replacement):
    result = [''] * length
    for i in range(length):
        result[i] = replacement if array[i] == 'X' else array[i]
    return result

def check_pattern(str_arr, suffix, n, un):
    if n < 2:
        return 0
    last_char = suffix[1]
    first_char = suffix[0]
    if str_arr[n - 1] == '_' or str_arr[n - 1] == last_char:
        if str_arr[n - 2] == '_' or str_arr[n - 2] == first_char:
            return 10 ** un
    return 0

def process(str_arr, n):
    if n == 1 or str_arr[0] == '0':
        return 0
    count = 0
    underscore_count = 0
    for i in range(1, n - 2):
        if str_arr[i] == '_':
            underscore_count += 1
    count += check_pattern(str_arr, "25", n, underscore_count)
    count += check_pattern(str_arr, "50", n, underscore_count)
    count += check_pattern(str_arr, "75", n, underscore_count)
    if n > 2 and (str_arr[0] == '_' or str_arr[0] == '0'):
        count *= 9
    if n >= 3:
        if (str_arr[n - 1] == '_' or str_arr[n - 1] == '0') and (str_arr[n - 2] == '_' or str_arr[n - 2] == '0'):
            temp = 10 ** underscore_count
            if str_arr[0] == '_':
                temp *= 9
            count += temp
    return count

def main():
    input_str = sys.stdin.read().splitlines()
    test_cases = 1
    output = []
    index = 0
    while test_cases > 0:
        line = input_str[index].strip()
        index += 1
        input_str_arr = list(line)
        length = len(input_str_arr)
        if length == 1:
            if input_str_arr[0] in ['0', '_', 'X', '1']:
                output.append("1")
                test_cases -= 1
                continue
        total_count = 0
        has_x = 'X' in input_str_arr
        if has_x:
            for ch in '0123456789':
                generated_str = replace_x_with_char(input_str_arr, length, ch)
                total_count += process(generated_str, length)
        else:
            total_count += process(input_str_arr, length)
        output.append(str(total_count))
        test_cases -= 1
    print("\n".join(output))

if __name__ == "__main__":
    main()

